$testDb=new PDO('sqlite::memory:');$testDb->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$testDb->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);
function db():PDO{global $testDb;return $testDb;}
function query(string $sql,array $params=[]):PDOStatement{$s=db()->prepare($sql);$s->execute($params);return $s;}
function demand(bool $ok,string $message):void{if(!$ok)throw new InvalidArgumentException($message);}
function text_length(string $v):int{return strlen($v);}
function campus_staff(?array $u):bool{return ($u['id']??'')==='professor'&&($u['verified_at']??null)!==null;}
function campus_controls(string $id):array{return ['muted'=>false,'read_only'=>false,'suspended'=>false];}
function settings():array{return ['app_key'=>str_repeat('isolated-test-key-',4)];}
require dirname(__DIR__).'/private/terms.php';
function expect_flex(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
query('CREATE TABLE users (id VARCHAR(32) PRIMARY KEY,email TEXT,display_name TEXT,verified_at TEXT)');query('CREATE TABLE course_students (user_id TEXT,student_sequence INTEGER,full_name TEXT)');query('CREATE TABLE academic_college_passes (user_id TEXT,module_index INTEGER)');query('CREATE TABLE campus_audit (actor_id TEXT,action TEXT,subject TEXT,detail_json TEXT,created_at TEXT)');query('CREATE TABLE assessment_attempts (id TEXT,user_id TEXT,assessment_key TEXT,passed INTEGER,submitted_at TEXT,paper_json TEXT,result_json TEXT,score INTEGER,maximum INTEGER)');
