term_save_practice($users['alice'],['offering'=>$off['id'],'week'=>9,'notes'=>'Private reading-ahead notes are study work, not an awarded module pass.','version'=>0],$now);expect_flex(term_class_payload($users['alice'],$off['id'],9,$now)['practice']['notes']!=='','Reading-ahead practice notes should save without an opening paper or earlier quiz.');expect_flex(!term_passed('alice',$off['id'],'w10'),'Saving notes must not invent mastery.');
