function flex_credit(string $user,string $offering,string $part,string $at):void{if(!term_passed($user,$offering,$part))query('INSERT INTO assessment_attempts VALUES (?,?,?,?,?,?,?,?,?)',[bin2hex(random_bytes(8)),$user,term_assessment_key($offering,$part),1,$at,'{}','{}',10,10]);}
function flex_accepted_module(array $en,int $module,string $at):void{foreach(['opening','closing'] as $task){$id=bin2hex(random_bytes(16));query('INSERT INTO term_papers (id,enrollment_id,week_index,task_kind,revision,document_json,word_count,status,originality,peer_consent,consent_version,teacher_status,updated_at,submitted_at) VALUES (?,?,?,?,1,?,300,?,1,1,?,?,?,?)',[$id,$en['id'],$module,$task,'{}','submitted',TERM_CONSENT_VERSION,'accepted',$at,$at]);query('INSERT INTO term_peer_routes (paper_id,outcome,reason,decided_at) VALUES (?,?,?,?)',[$id,'professor_fallback','Explicit professor-only fixture route; no peer grade.',$at]);}}
for($module=0;$module<6;$module++){flex_accepted_module($en,$module,$time);flex_credit('alice',$off['id'],'w'.sprintf('%02d',$module+1),$time);}
