$progress=term_progress_for_enrollment($en,'alice');expect_flex($progress['nextModule']===5,'Resume must point to Module 6 when its mid-course requirement is pending.');flex_credit('alice',$off['id'],'m',$time);expect_flex(term_writing_available($en,$off,6,$now),'The same-day mid-course pass should open Module 7 assessed work.');
