$preview=term_curriculum_preview($prof,'philosophy',9);expect_flex($preview['preview']&&$preview['enrollment']===null&&!isset($preview['content']['questions']),'Faculty preview must remain separate from student enrollment and private exam keys.');
terms_run_due($now+84*86400-1);expect_flex(query('SELECT status FROM term_enrollments WHERE user_id=?',['carol'])->fetchColumn()==='enrolled','A nonstarter must not expire before 84 days from enrollment.');terms_run_due($now+84*86400);expect_flex(query('SELECT status FROM term_enrollments WHERE user_id=?',['carol'])->fetchColumn()==='unenrolled_inactive','A never-started enrollment should expire after its own 84 days.');expect_flex(query('SELECT status FROM term_enrollments WHERE user_id=?',['alice'])->fetchColumn()==='enrolled'&&query('SELECT status FROM term_enrollments WHERE user_id=?',['bob'])->fetchColumn()==='enrolled','Active notes and saved drafts must prevent a hard plan-end lockout.');
term_save_practice($users['alice'],['offering'=>$off['id'],'week'=>9,'notes'=>'Continued study beyond the recommended plan.','version'=>1],$now+100*86400);expect_flex(term_quiz_eligible(term_quiz_paper(term_assessment_key($off['id'],'f')),'alice',$now+100*86400),'Active learners retain final eligibility after the recommended plan.');$same=term_enroll($users['alice'],'ai-business',$now+100*86400,$consent);expect_flex($same['enrollment']['id']===$en['id'],'Reopening an active course should resume its enrollment rather than create a duplicate intake.');$again=term_enroll($users['carol'],'ai-business',$now+100*86400,$consent);expect_flex($again['enrollment']['id']!==term_enrollment($users['carol'],$off['id'])['id'],'An inactive learner can enroll again without rewriting the earlier record.');
echo "PASS: immediate all-module reading, sequential assessed mastery, unrestricted private notes, same-day mid/final eligibility, mastery-based resume, six-place intake cap, saved-draft participation and nonstarter-only 84-day expiry.\n";
